"""Generate honest, camera-free editorial pages from the existing catalog.
Does not alter CAD, print packs, catalog metadata, hosting identity or sharing.
"""
from pathlib import Path
import html, json, zipfile, io
ROOT=Path(__file__).resolve().parents[1]; D=ROOT/'dist'
content=json.loads((D/'editorial-data.json').read_text()); catalog=json.loads((D/'catalog.json').read_text()); designs={d['id']:d for d in catalog}
products={p['id']:p for p in content['product_pages']}; concepts={c['id']:c for c in content['concepts']}; sources={s['id']:s for s in content['sources']}
e=lambda value:html.escape(str(value),quote=True)
def page(title,desc,body,depth=1,script=False):
 prefix='../'*depth
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{e(desc)}"><meta name="theme-color" content="#0b211b"><title>{e(title)} | NestForge</title><link rel="stylesheet" href="{prefix}content.css"></head><body class="content-page"><a class="skip-link" href="#content">Skip to content</a><header class="content-header"><a class="content-brand" href="{prefix}">NESTFORGE</a><nav aria-label="Main navigation"><a href="{prefix}#collection">All print designs</a><a href="{prefix}themes/">Themes & ideas</a><a href="{prefix}downloads/">Print library</a></nav></header><main id="content" class="content-main" tabindex="-1">{body}</main><footer class="content-footer"><span>Original little worlds · No electronics required</span><a href="{prefix}">Back to the garden</a><span>Digital prototypes, not certified products</span></footer>{f'<script type="module" src="{prefix}shortlist.js"></script>' if script else ''}</body></html>'''
def write(path,text):path.parent.mkdir(parents=True,exist_ok=True);path.write_text(text+'\n')
def href(id,prefix):return f'{prefix}designs/{id}/' if id in products else f'{prefix}#{id}'
def button(url,label,primary=False,download=False):return f'<a class="button-{ "primary" if primary else "secondary"}" href="{e(url)}"{ " download" if download else ""}>{e(label)}</a>'
def source_note(source_id):
 if not source_id:return 'Exploratory hypothesis; no suitable category-level feeder demand evidence verified.'
 s=sources[source_id];return f'<a href="{e(s["url"])}" target="_blank" rel="noopener noreferrer">{e(s["title"])}</a> ({e(s["published"])}). Adjacent-market context, not proof of feeder demand.'
def sketch(id):
 # Original schematic illustrations. These are deliberately not photorealistic
 # renders and carry their concept status inside the image itself.
 common='''<defs><pattern id="grid" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M24 0H0V24" fill="none" stroke="#658875" stroke-opacity=".12"/></pattern></defs><rect width="640" height="430" rx="14" fill="#162d25"/><rect x="20" y="20" width="600" height="390" fill="url(#grid)"/><text x="32" y="47" fill="#b9d1b9" font-family="sans-serif" font-size="12" letter-spacing="2">ORIGINAL CONCEPT STUDY · NOT CAD</text>'''
 shapes={
 'toadstool-terrace':'''<path d="M317 82v-20m0 20c-18 0-24 18-21 31h42c3-13-3-31-21-31Z" stroke="#e6cf9d" stroke-width="6" fill="none"/><ellipse cx="320" cy="329" rx="134" ry="36" fill="#0a1b16"/><path d="M279 169h82l-10 139h-62Z" fill="#d0c1a1" stroke="#9eaa87" stroke-width="3"/><path d="M171 304q149-56 298 0v25q-149 64-298 0Z" fill="#8fa576" stroke="#d6dfb8" stroke-width="3"/><ellipse cx="320" cy="304" rx="149" ry="31" fill="#4e6548" stroke="#d6dfb8" stroke-width="3"/><path d="M270 277h100v30H270Z" fill="#d0c1a1"/><path d="M150 184q35-92 167-97 133 4 173 97-165 48-340 0Z" fill="#b96c47" stroke="#e6b48b" stroke-width="3"/><ellipse cx="247" cy="144" rx="23" ry="9" fill="#e9d5aa" transform="rotate(-14 247 144)"/><ellipse cx="356" cy="123" rx="25" ry="10" fill="#e9d5aa"/><ellipse cx="409" cy="160" rx="19" ry="8" fill="#e9d5aa"/><path d="M482 170h87M466 322h103M272 259H94" stroke="#9fb79a" stroke-width="1.5"/><g fill="#e2e9ca" font-family="sans-serif" font-size="12"><text x="492" y="158">Lift-off cap</text><text x="479" y="346">Ring tray</text><text x="35" y="251">Central hopper</text></g>''',
 'storybook-nook':'''<path d="M188 105h30v233h-30Z" fill="#a2b08b"/><path d="M145 210 295 80 350 112 200 242Z" fill="#d7caa7" stroke="#ede4c7" stroke-width="3"/><path d="M295 80 445 210 500 242 350 112Z" fill="#a99b78" stroke="#ede4c7" stroke-width="3"/><path d="M200 242 350 112 500 242v15L350 127 200 257Z" fill="#c4b18b" stroke="#e5dab4" stroke-width="2"/><path d="m211 232 139-120 139 120M220 239l130-112 130 112" stroke="#857c65" stroke-width="2" fill="none"/><path d="m295 80 55 32" stroke="#5b754f" stroke-width="9"/><path d="M200 193h35v120h-35Z" fill="#54724f"/><path d="m227 291 172-7 68 31-172 21Z" fill="#728c61" stroke="#cfdda9" stroke-width="3"/><path d="m227 291 68 45v25l-68-44ZM295 336l172-21v25l-172 21Z" fill="#a6b282" stroke="#cfdda9" stroke-width="2"/><path d="m330 359 110 20m-14-12 14 12-20 4" stroke="#f1b26d" stroke-width="3" fill="none"/><path d="M461 184h102M188 225H82" stroke="#a7ba9b" stroke-width="1.5"/><g fill="#e2e9ca" font-family="sans-serif" font-size="12"><text x="485" y="173">Book roof</text><text x="36" y="214">Fixed backplate</text><text x="343" y="402">Side-pull seed drawer</text></g>''',
 'comet-diner':'''<path d="M290 290h36v88h-36Z" fill="#7b8c72"/><path d="m157 165 265-25 52 54-264 35Z" fill="#d2c7a3" stroke="#ebe1bc" stroke-width="3"/><path d="m157 165 53 64v24l-53-63ZM210 229l264-35v24l-264 35Z" fill="#bb7754" stroke="#e4bb95" stroke-width="2"/><path d="m437 147 35-57 13 104Z" fill="#9db0a0" stroke="#d8e5d3" stroke-width="3"/><path d="M174 203h28v107h-28ZM435 229h23v69h-23Z" fill="#7b9b83"/><path d="m172 290 246-24 61 34-239 37Z" fill="#b6bea2" stroke="#d8e5bd" stroke-width="3"/><path d="m240 337 239-37v22l-239 37Z" fill="#758d70" stroke="#d8e5bd" stroke-width="2"/><path d="m226 298 170-17 38 17-171 24Z" fill="#354d39" stroke="#94b18a" stroke-width="3"/><rect x="281" y="212" width="95" height="64" rx="7" fill="#d3ba8a" stroke="#f0d5a0" stroke-width="3"/><path d="M376 241h190M465 184h101M278 345H75" stroke="#a7ba9b" stroke-width="1.5"/><g fill="#e2e9ca" font-family="sans-serif" font-size="12"><text x="490" y="174">Rain canopy</text><text x="455" y="259">Rear cassette</text><text x="39" y="369">Front trough + perch</text></g>''',
 'courtside-canopy':'''<path d="M239 146h28v184h-28ZM417 143h27v151h-27Z" fill="#8a9a7a"/><path d="m160 302 260-30 72 47-268 43Z" fill="#547e68" stroke="#c1d5a6" stroke-width="3"/><path d="m224 362 268-43v20l-268 44Z" fill="#254f42" stroke="#9fbc91" stroke-width="2"/><path d="m198 305 204-23 50 34-211 32Z" fill="none" stroke="#d9d7b5" stroke-width="3"/><path d="m301 292 22 47m-35-22q17-16 37-3-15 17-37 3Z" stroke="#d9d7b5" stroke-width="2" fill="none"/><ellipse cx="255" cy="312" rx="27" ry="12" fill="#102c24" stroke="#e4b47a" stroke-width="7"/><ellipse cx="393" cy="294" rx="27" ry="12" fill="#102c24" stroke="#e4b47a" stroke-width="7"/><path d="m181 166q96-82 273-38l44 47q-177-45-270 43Z" fill="#c79858" stroke="#e8d4aa" stroke-width="3"/><path d="M461 150h113M421 296h153M241 252H73" stroke="#a7ba9b" stroke-width="1.5"/><g fill="#e2e9ca" font-family="sans-serif" font-size="12"><text x="510" y="137">Curved visor</text><text x="465" y="319">Lift-out cups</text><text x="34" y="243">Fixed mount</text></g>'''}
 common=common.replace('id="grid"',f'id="grid-{id}"').replace('url(#grid)',f'url(#grid-{id})')
 title=e(concepts[id]['name']);return f'<svg class="sketch" role="img" aria-label="Concept sketch of {title}; not a CAD model or print file" viewBox="0 0 640 430" xmlns="http://www.w3.org/2000/svg"><title>{title} — unbuilt concept sketch</title>{common}{shapes[id]}</svg>'

def shortlist_button(id):return f'<button class="button-secondary shortlist-button" data-concept-id="{e(id)}" aria-pressed="false">Save to my shortlist</button>'

# Six existing build pages: all measurements, parts and downloads are source-backed.
for id,copy in products.items():
 d=designs[id];folder=D/'models'/id;plan=json.loads((folder/'print-plan.json').read_text())
 with zipfile.ZipFile(folder/f'{id}-X1C.zip') as pack:
  with zipfile.ZipFile(io.BytesIO(pack.read(id+'/'+plan['plates'][0]['file']))) as plate:settings=json.loads(plate.read('Metadata/project_settings.config'))
 materials=' / '.join(dict.fromkeys(settings['filament_type']))
 size=[max(p['bounds'][i+3] for p in d['parts'])-min(p['bounds'][i] for p in d['parts']) for i in range(3)]
 dimension=' × '.join(str(round(n)) for n in size);time='–'.join(f'{n:g}' for n in plan['total_time_hours'])
 prefix='../../';asset=f'{prefix}models/{id}/'
 facts=''.join(f'<div><strong>{e(value)}</strong><span>{e(label)}</span></div>' for value,label in [(len(d['parts']),'printed pieces'),(plan['plate_count'],'X1C plates'),(d['color_count'],'design colors')])
 platecards=''.join(f'<article><img src="{asset}{e(p["preview"])}" alt="Actual arranged print plate {p["number"]} for {e(d["name"])}" width="610" height="500" loading="lazy"><h3>Plate {p["number"]}</h3><p>{p["piece_count"]} piece(s) · {len(p["colors"])} color(s) · {p["time_hours"][0]:g}–{p["time_hours"][1]:g} h estimate</p><ul>'+''.join('<li>'+e(x)+'</li>' for x in p['parts'])+'</ul></article>' for p in plan['plates'])
 parts=''.join(f'<li><strong>{e(p["name"])}</strong><br>{e(p.get("support","Inspect the sliced preview for support requirements."))}</li>' for p in d['parts'])
 assembly=''.join('<li>'+e(x)+'</li>' for x in d['assembly']);notes=''.join('<li>'+e(x)+'</li>' for x in d.get('notes',[]))
 body=f'''<div class="product-hero"><figure class="product-image"><img src="{asset}preview.png" alt="CAD render of {e(d['name'])}; not a physical prototype photograph" width="600" height="650"><figcaption>Actual existing CAD preview. No physical performance is established by this render.</figcaption></figure><div class="product-hero-copy"><span class="eyebrow">{e(copy['theme'])}</span><h1>{e(d['name'])}</h1><span class="pill">PRINT FILES AVAILABLE · NO CAMERA REQUIRED</span><p class="lede">{e(copy['lead'])}</p><p>{e(copy['use'])}</p><div class="fact-grid">{facts}</div><p>{dimension} mm printed assembly · {time} hours planning estimate.</p><div class="button-row">{button(asset+id+'-X1C.zip','Download print pack ↓',True,True)}{button(asset+d['cad_download'],'Assembly CAD ZIP ↓',False,True)}{button(prefix+'#'+id,'Interactive 3D & ASA palette')}</div><p class="prototype-note">Digital prototype. Print files are present, but physical fit, hanging load, seed flow and weather resistance still need testing. These are downloads, not a finished feeder for sale.</p></div></div><section class="content-section content-columns"><div><span class="eyebrow">THE PRACTICAL PART</span><h2>Refill. Clean. Repeat.</h2><p>{e(d.get('refill','Follow the assembly instructions.'))}</p><p>{e(copy['watch'])}</p><h3>What you need</h3><p>A suitable printer, compatible filament, and appropriate outdoor suspension hardware. The integral eye suspends the assembled feeder; the cord or support is not a printed part. No camera, batteries, app or subscription are needed.</p><p>Supplied 3MF filament type: <strong>{e(materials)}</strong>. ASA is an outdoor alternative, not a drop-in profile substitution: change the profile, re-slice and test the fit. Use manufacturer ventilation guidance.</p><p>{button(prefix+'downloads/NestForge-CAD-Source.zip','Download editable source ZIP',False,True)}</p></div><div><h2>Assembly sequence</h2><ol>{assembly}</ol><h3>Part-specific support notes</h3><ul>{parts}</ul></div></section><section class="content-section"><span class="eyebrow">ACTUAL PACK CONTENTS</span><h2>Your print plan</h2><p>The complete ZIP contains these native X1C 3MF plates, STL parts and assembly notes. Files are unsliced: inspect each plate in Bambu Studio. Time ranges are planning estimates, not measured printer runs; supports and your profile can change the result.</p><div class="plate-cards">{platecards}</div><div class="button-row">{button(prefix+'#'+id,'Open individual plate downloads')}{button(asset+id+'-X1C.zip','Download all plates in the print pack',True,True)}</div></section><section class="content-section"><h2>Before hanging it outdoors</h2><ul>{notes}</ul><p>Use shallow daily portions, remove wet seed, keep drains open, and inspect joints and suspension points. Test near the ground before installing over people, pets or property.</p><p><a class="text-link" href="{prefix}themes/">Explore another camera-free theme →</a></p></section>'''
 write(D/'designs'/id/'index.html',page(d['name']+' — build page',copy['lead'],body,2))
write(D/'product-pages.js','export const productPageIds = '+json.dumps(list(products))+';')

# Separate concept pages never get print downloads or catalog entries.
for id,c in concepts.items():
 prefix='../../';related=''.join(button(href(r,prefix),designs[r]['name']) for r in c['related'])
 proposed=''.join(f'<article><h3>{label}</h3><p>{e(c[key])}</p></article>' for label,key in [('Different on purpose','silhouette'),('Feeding system','feeding'),('Refill & cleaning','service'),('Mounting approach','mounting'),('Proposed print breakdown','parts')])
 body=f'''<div class="product-hero concept-hero"><div>{sketch(id)}<p class="sketch-caption">Original schematic. Shapes, dimensions and connections are not validated CAD.</p></div><div class="product-hero-copy"><span class="eyebrow">{e(c['theme'])} · IDEA {c['priority']:02}</span><h1>{e(c['name'])}</h1><span class="pill concept">CONCEPT ONLY · NO PRINT FILES</span><p class="lede">{e(c['lead'])}</p><p class="prototype-note">This is an unbuilt design study. No CAD, STL, STEP, 3MF, print time, filament weight, price or physical test result is available. It is not ready to print, order or reserve.</p><div class="button-row">{shortlist_button(id)}{button('../','Compare all four concepts')}</div><p class="source-note">Shortlists stay in this browser. Nothing is submitted and no vote count is claimed.</p><p id="shortlist-status" role="status" aria-live="polite"></p></div></div><section class="content-section"><h2>How this could work</h2><p>Design intent, not a claim that these mechanisms have been engineered or tested.</p><div class="proposal-grid">{proposed}</div></section><section class="content-section content-columns"><div><h2>Tests before this becomes a product</h2><ol>{''.join('<li>'+e(x)+'</li>' for x in c['tests'])}</ol><p>Before any download release: finish measured CAD, verify every connected solid and drain, arrange the real parts on plates, run a native slicer roundtrip, then perform fit, cleaning, seed-flow and load trials.</p></div><div><h2>Why explore this direction?</h2><p class="source-note">{source_note(c.get('source'))}</p><p>Our theme-to-feeder interpretation is a hypothesis. A familiar aesthetic does not establish purchase intent, and the illustration is not a customer review or licensed collaboration.</p><p>Original geometry and naming should remain independent of protected characters, logos, book covers and recognizable franchise props.</p></div></section><section class="content-section"><h2>Want files instead of a concept?</h2><p>These existing no-camera designs already have downloadable print packs. They remain digital prototypes requiring physical checks.</p><div class="button-row">{related}</div></section>'''
 write(D/'concepts'/id/'index.html',page(c['name']+' — concept only',c['lead'],body,2,True))
# A stable concept index makes the sibling navigation above work with no JavaScript.
write(D/'concepts'/'index.html',page('New camera-free concepts','Four original design studies. No CAD or print files are available for these concepts.','<div class="content-intro"><span class="eyebrow">ORIGINAL IDEAS · CLEAR STATUS</span><h1>Four different ways to feed.</h1><p class="lede">These are design studies, not more near-identical finished products. No camera required; no download or buildability promise.</p></div><div class="idea-grid">'+''.join(f'<article class="idea-card">{sketch(c["id"])}<div class="card-copy"><span class="pill concept">CONCEPT ONLY</span><h2>{e(c["name"])}</h2><p>{e(c["lead"])}</p>{button(c["id"]+"/","Read the design brief")}</div></article>' for c in concepts.values())+'</div>',1))

cards=''
for t in content['themes']:
 links=''.join(f'<li><a href="{href(id,"../")}">{e(designs[id]["name"])} <span>Existing files →</span></a></li>' for id in t['ids'])
 concept_link=button('../concepts/'+t['concept']+'/','New concept: '+concepts[t['concept']]['name']) if t.get('concept') else ''
 cards+=f'<article id="{e(t["id"])}" class="theme-card"><img src="../models/{t["hero"]}/preview.png" alt="Existing CAD render: {e(designs[t["hero"]]["name"])}" width="600" height="650" loading="lazy"><div class="card-copy"><span class="eyebrow">{e(t["tagline"])}</span><h2>{e(t["name"])}</h2><p>{e(t["description"])}</p><ul class="theme-links">{links}</ul>{concept_link}</div></article>'
ideas=''.join(f'<article class="idea-card">{sketch(c["id"])}<div class="card-copy"><span class="pill concept">CONCEPT ONLY · NO FILES</span><h3>{e(c["name"])}</h3><p>{e(c["lead"])}</p><div class="button-row">{button("../concepts/"+c["id"]+"/","Read the concept")}{shortlist_button(c["id"])}</div></div></article>' for c in concepts.values())
retail=''.join(f'<li><a class="text-link" href="{e(r["url"])}" target="_blank" rel="noopener noreferrer">{e(r["title"])}</a>: {e(r["finding"])}</li>' for r in content.get('retail_crosscheck',[]))
rows=''.join(f'<tr><th scope="row">{e(t["name"])}</th><td>{e(t["priority"])}</td><td>{e(t["reason"])}</td><td>{source_note(t.get("source"))}</td></tr>' for t in content['themes'])
body=f'''<div class="content-intro"><span class="eyebrow">NO CAMERA. NO APP. YOUR KIND OF GARDEN.</span><h1>Find your little world.</h1><p class="lede">Start with a theme that feels like you, not a box of electronics. Explore the existing printable collection, then see what we could make next.</p><p>37 camera-free designs with existing files. Four new original concepts are shown separately and have <strong>no print downloads</strong>.</p><div class="button-row">{button('../#collection','Browse all existing print files',True)}{button('#new-concepts','See four new concepts')}{button('#why-these-themes','Why these themes?')}</div></div><div class="theme-grid">{cards}</div><section id="new-concepts" class="content-section"><span class="eyebrow">BEYOND THE EXISTING COLLECTION</span><h2>Four ideas. Four different structures.</h2><p>No cosmetic reskins or borrowed franchise props. These original studies explore different feeding surfaces, refill paths and mounting arrangements. They have not been modeled, printed or validated.</p><div class="idea-grid">{ideas}</div><div class="shortlist-box"><h3>Your idea shortlist</h3><p>Saved only in this browser. This is a personal comparison tool, not a public vote, mailing list or preorder. No data is sent to NestForge.</p><ul id="shortlist-items" class="shortlist-items"></ul><p id="shortlist-status" role="status" aria-live="polite">Choose an idea to start a shortlist.</p><button id="export-shortlist" class="button-secondary" disabled>Download my shortlist</button></div></section><section id="why-these-themes" class="content-section"><span class="eyebrow">EVIDENCE, NOT BESTSELLER CLAIMS</span><h2>Designed for more than our own taste.</h2><p>{e(content['research_note'])} We prioritize recent, related evidence over sheer enthusiasm, and preserve lower-evidence ideas as comparison tests.</p><p class="source-note">{e(sources['etsy-fall-2026']['signal'])} {e(sources['etsy-fall-2026']['scope'])} <a href="{sources['etsy-fall-2026']['url']}" target="_blank" rel="noopener noreferrer">Read the source →</a></p><div class="evidence-scroll"><table class="evidence-table"><caption>Research priority, not a sales ranking · reviewed October 23, 2026</caption><thead><tr><th>Theme</th><th>Priority</th><th>Our interpretation</th><th>Source & limit</th></tr></thead><tbody>{rows}</tbody></table></div><h3>Reality check: the existing feeder market</h3><ul>{retail}</ul><p class="source-note">Official-store observations from October 23, 2026. Listings show category presence, not units sold or willingness to pay for these concepts.</p><p>Next validation: compare equal-quality mockups with people who actually feed birds; ask which they would print or buy, what they would pay, and what would make cleaning or refill easier. Do not label a favorite a bestseller or develop expensive CAD from aesthetic search growth alone.</p><p>Current shopper demand is still unmeasured for these exact ideas. No fabricated reviews, popularity counters, licensed partnerships, stock or finished-product availability are presented.</p></section>'''
write(D/'themes'/'index.html',page('Camera-free themes & original concepts','Existing printable bird feeders in six themes, plus four clearly marked original camera-free concepts.',body,1,True))
print(f'Built {len(products)} source-backed product pages, {len(concepts)} concept pages, and theme/concept indexes. No CAD changed.')
